  function render(){
    if(items.length === 0){
      listEl.innerHTML = '<div class="empty">No links saved yet. Paste one above to get started.</div>';
      return;
    }
    listEl.innerHTML = '';
    items.forEach(function(it){
      var el = document.createElement('div');
      el.className = 'item';
      el.innerHTML =
