  function save(){
    var raw = urlEl.value.trim();
    if(!raw) return;
    var url = normalize(raw);
    var title = titleEl.value.trim() || titleFromUrl(url);
    items.unshift({ url:url, title:title, saved:new Date() });
    urlEl.value=''; titleEl.value=''; refreshButton();
    render(); urlEl.focus();
    toast('Saved “'+title+'”');
  }

  urlEl.addEventListener('input', refreshButton);
